//! Sky of the map: a cubemap from a CC0 Poly Haven panorama (source in
//! `assets/sky/SOURCES.md`), generated by `tools/sky.py` with its sun turned
//! towards the sun light of `world.rs`, and embedded in the binary.

use bevy::asset::RenderAssetUsages;
use bevy::image::{CompressedImageFormats, Image, ImageSampler, ImageType};
use bevy::light::Skybox;
use bevy::prelude::*;
use bevy::render::render_resource::{TextureViewDescriptor, TextureViewDimension};

/// Six square faces stacked vertically, wgpu order (+X, -X, +Y, -Y, +Z, -Z).
const SKY: &[u8] = include_bytes!("../../../assets/sky/sky.png");

/// Luminance of a white texel in cd/m²: with the default camera exposure the
/// brightest clouds sit just under white, below the sunlit walls.
const BRIGHTNESS: f32 = 1000.0;

/// Skybox component for the main camera.
pub fn skybox(images: &mut Assets<Image>) -> Skybox {
    Skybox {
        image: Some(images.add(cubemap())),
        brightness: BRIGHTNESS,
        ..default()
    }
}

fn cubemap() -> Image {
    let mut img = Image::from_buffer(
        SKY,
        ImageType::Extension("png"),
        CompressedImageFormats::NONE,
        true,
        ImageSampler::linear(),
        RenderAssetUsages::RENDER_WORLD,
    )
    .expect("sky.png embedded in the binary");
    img.reinterpret_stacked_2d_as_array(6)
        .expect("sky.png is six square faces stacked vertically");
    img.texture_view_descriptor = Some(TextureViewDescriptor {
        dimension: Some(TextureViewDimension::Cube),
        ..default()
    });
    img
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The sun (mean direction of the saturated texels) lies towards the sun
    /// light of `world.rs`, read back with the lookup of Bevy's skybox shader
    /// (z negated).
    #[test]
    fn sun_matches_the_sun_light() {
        let img = cubemap();
        let size = img.width() as usize;
        assert_eq!(img.texture_descriptor.size.depth_or_array_layers, 6);
        let data = img.data.as_ref().unwrap();
        let dir: Vec3 = data
            .as_chunks::<4>()
            .0
            .iter()
            .enumerate()
            .filter(|(_, p)| p[..3] == [255; 3])
            .map(|(i, _)| {
                let (face, y, x) = (i / (size * size), i / size % size, i % size);
                let s = (x as f32 + 0.5) / size as f32 * 2.0 - 1.0;
                let t = (y as f32 + 0.5) / size as f32 * 2.0 - 1.0;
                let c = [
                    Vec3::new(1.0, -t, -s),
                    Vec3::new(-1.0, -t, s),
                    Vec3::new(s, 1.0, t),
                    Vec3::new(s, -1.0, -t),
                    Vec3::new(s, -t, 1.0),
                    Vec3::new(-s, -t, -1.0),
                ][face];
                Vec3::new(c.x, c.y, -c.z).normalize()
            })
            .sum::<Vec3>()
            .normalize();
        let sun = crate::world::SUN_OFFSET.normalize();
        // Same azimuth; the panorama's own sun is a little lower (~49° vs 59°).
        let az = |v: Vec3| v.x.atan2(-v.z);
        assert!((az(dir) - az(sun)).abs() < 0.1, "sky sun at {dir}");
        assert!((0.6..0.9).contains(&dir.y), "sky sun at {dir}");
    }
}
